import express from "express";
import { type } from "arktype";

// Schema for POST /users body
const UserBodySchema = type({
  username: "string.alphanumeric >= 3 <= 20",
  email: "string.email",
  age: "number.integer >= 13 <= 120?"
});

// Schema for GET /search query (uses |> morph pipeline for string->number coercion)
const SearchQuerySchema = type({
  q: "string >= 1 <= 100",
  page: "string.numeric.parse |> number >= 1",
  limit: "string.numeric.parse |> 1 <= number <= 50"
});

// Minimal structural type for any object that satisfies the Standard Schema spec.
// Reference: https://standardschema.dev
interface StandardSchemaV1<Input = unknown, Output = Input> {
  readonly "~standard": {
    readonly version: 1;
    readonly vendor: string;
    readonly validate: (value: unknown) => StandardSchemaV1.Result<Output> | Promise<StandardSchemaV1.Result<Output>>;
  };
}
namespace StandardSchemaV1 {
  type Result<Output> = SuccessResult<Output> | FailureResult;
  interface SuccessResult<Output> {
    readonly value: Output;
    readonly issues?: undefined;
  }
  interface FailureResult {
    readonly issues: ReadonlyArray<Issue>;
  }
  interface Issue {
    readonly message: string;
  }
}

// Reusable middleware factory that drives validation through the
// vendor-neutral Standard Schema interface (`schema["~standard"].validate`).
function validate(source: "body" | "query", schema: StandardSchemaV1) {
  return async (req: express.Request, res: express.Response, next: express.NextFunction) => {
    try {
      const result = await schema["~standard"].validate(req[source]);
      if (result.issues) {
        res.status(400).json({
          issues: result.issues.map((issue) => ({ message: issue.message }))
        });
        return;
      }
      // Success: replace the source with the validated/coerced value.
      (req as any)[source] = result.value;
      next();
    } catch (err) {
      next(err);
    }
  };
}

const app = express();
app.use(express.json());

app.post("/users", validate("body", UserBodySchema), (req, res) => {
  res.status(201).json(req.body);
});

app.get("/search", validate("query", SearchQuerySchema), (req, res) => {
  res.status(200).json(req.query);
});

app.listen(3000, () => {
  console.log("Server listening on port 3000");
});
